quiz.answer:
declare const require: any; // 標準入力を読むための宣言(消さない)
const input: string = require("fs").readFileSync(0, "utf8");
const lines: string[] = input.split("\n").filter((l: string) => l.trim() !== "");

function sum(prices: number[]): number {
  let s = 0;
  for (const p of prices) {
    s += p;
  }
  return s;
}

const prices: number[] = lines.length === 0 ? [] : lines[0].trim().split(/\s+/).map(Number);
console.log(`件数: ${prices.length}`);
console.log(`合計: ${sum(prices)}円`);

