quiz.answer:
declare const require: any; // 標準入力を読むための宣言(消さない)
const input: string = require("fs").readFileSync(0, "utf8");
const lines: string[] = input.split("\n").filter((l: string) => l.trim() !== "");

function formatTags(tags: string[]): string {
  if (tags.length === 0) {
    return "(タグなし)";
  }
  return tags.map((t) => `#${t}`).join(" ");
}

const tags: string[] = lines.length === 0 ? [] : lines[0].split(",");
console.log(formatTags(tags));
